37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.service.ClinicService;
39	import org.springframework.security.access.prepost.PreAuthorize;
40	import org.springframework.web.bind.annotation.CrossOrigin;
41	import org.springframework.web.bind.annotation.RequestMapping;
42	import org.springframework.web.bind.annotation.RestController;
43	import org.springframework.web.server.ResponseStatusException;
44	import org.springframework.web.util.UriComponentsBuilder;
45	
46	import jakarta.transaction.Transactional;
47	
48	/**
49	 * @author Vitaliy Fedoriv
50	 */
51	
52	@RestController
53	@CrossOrigin(exposedHeaders = "errors, content-type")
54	@RequestMapping("/api")
55	public class OwnerRestControllerV1 implements OwnersApi {
56	
57	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
58	
59	    private static final org.slf4j.Logger NOTIFY = org.slf4j.LoggerFactory.getLogger("NOTIFY");
60	
61	    /**
62	     * Monotonically increasing sequence assigned to each {@code OWNER_CREATED} structured event, in
63	     * the order owners are created across this application instance. Shared across all requests.
64	     */
65	    private static final java.util.concurrent.atomic.AtomicLong OWNER_EVENT_SEQ =
66	        new java.util.concurrent.atomic.AtomicLong();
67	
68	    /** Serializes the immutable {@link OwnerCreatedEvent} to its canonical JSON form. */
69	    private static final tools.jackson.databind.ObjectMapper AUDIT_EVENT_MAPPER =
70	        tools.jackson.databind.json.JsonMapper.builder().build();
71	
72	    /**
73	     * Immutable structured audit event emitted alongside the human-readable audit line when an owner
74	     * is created. Its component order is also its JSON field order: {@code seq}, {@code ownerId},
75	     * {@code memberId}, {@code membershipLevel}, {@code event}. The {@code memberId} component carries
76	     * the owner's unified primary identifier.
77	     */
78	    private record OwnerCreatedEvent(long seq, Integer ownerId, String memberId,
79	        Integer membershipLevel, String event) {
80	    }
81	
82	    /**
83	     * Remembers, per seen {@code Idempotency-Key} header, the id of the owner originally created for
84	     * that key, so a repeated create carrying the same key returns that owner instead of creating a
85	     * duplicate. Kept in memory and keyed on the opaque client-supplied value.
86	     */
87	    private static final java.util.Map<String, Integer> IDEMPOTENCY_KEYS =
88	        new java.util.concurrent.ConcurrentHashMap<>();
89	
90	    private final ClinicService clinicService;
91	
92	    private final OwnerMapper ownerMapper;
93	
94	    private final PetMapper petMapper;
95	
96	    private final VisitMapper visitMapper;
97	
98	    public OwnerRestControllerV1(ClinicService clinicService,
99	                                 OwnerMapper ownerMapper,
100	                                 PetMapper petMapper,
101	                                 VisitMapper visitMapper) {
102	        this.clinicService = clinicService;
103	        this.ownerMapper = ownerMapper;
104	        this.petMapper = petMapper;
105	        this.visitMapper = visitMapper;
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
111	        Collection<Owner> owners;
112	        if (lastName != null) {
113	            owners = this.clinicService.findOwnerByLastName(lastName);
114	        } else {
115	            owners = this.clinicService.findAllOwners();
116	        }
117	        if (owners.isEmpty()) {
118	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
119	        }
120	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
121	    }
122	
123	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
124	    @Override
125	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
126	        Owner owner = this.clinicService.findOwnerById(ownerId);
127	        if (owner == null) {
128	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
129	        }
130	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
131	    }
132	
133	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
134	    @Override
135	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
136	        // Idempotent create: if this request carries an 'Idempotency-Key' we have already seen, return
137	        // the owner originally created for that key with 200 OK, rather than creating a duplicate (which
138	        // the identity/household duplicate rules would otherwise reject with 409).
139	        String idempotencyKey = currentIdempotencyKey();
140	        if (idempotencyKey != null) {
141	            Integer existingId = IDEMPOTENCY_KEYS.get(idempotencyKey);
142	            if (existingId != null) {
143	                Owner existing = this.clinicService.findOwnerById(existingId);
144	                if (existing != null) {
145	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
146	                }
147	            }
148	        }
149	        HttpHeaders headers = new HttpHeaders();
150	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
151	        applyAddress(owner);
152	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
153	        owner.setTelephone(normalizedTelephone);
154	        owner.setEmail(normalizeEmail(owner.getEmail()));
155	        validateEmailDomain(owner.getEmail());
156	        validatePostcode(owner.getPostcode(), owner.getCity());
157	        java.time.LocalDate serverDate = java.time.LocalDate.now();
158	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(serverDate)) {
159	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
160	                "Registration date must not be later than the current server date");
161	        }
162	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() != null
163	            ? owner.getRegistrationDate() : serverDate;
164	        java.time.LocalDate businessDate = toBusinessDay(effectiveDate);
165	        owner.setRegistrationDate(businessDate);
166	        long createdToday = this.clinicService.findAllOwners().stream()
167	            .map(Owner::getRegistrationDate)
168	            .filter(businessDate::equals)
169	            .count();
170	        if (createdToday >= 100) {
171	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
172	                "The maximum number of owners for today has already been reached");
173	        }
174	        owner.setBulkSignupWarning(createdToday > 80);
175	        // The household is keyed deterministically on (normalized last name, postcode): every owner
176	        // computes the same householdId from those two fields, so owners sharing a last name and
177	        // postcode belong to the same household automatically, without any explicit linking.
178	        String lastNameKey = normalizeForHousehold(owner.getLastName());
179	        String householdId = householdId(lastNameKey, owner.getPostcode());
180	        owner.setHouseholdId(householdId);
181	        // Soft-deleted owners are excluded from all duplicate/identity detection: a deleted owner
182	        // no longer blocks a new owner that would otherwise match it.
183	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
184	            .filter(existing -> !existing.isDeleted())
185	            .filter(existing -> householdId.equals(
186	                householdId(normalizeForHousehold(existing.getLastName()), existing.getPostcode())))
187	            .toList();
188	        // All duplicate detection is expressed through the single derived identityKey, the SHA-256
189	        // hex of (normalizedTelephone|lowerEmail|soundex(lastName)); a new owner is rejected only
190	        // when its whole key matches an existing (non-deleted) owner's.
191	        String identityKey = owner.getIdentityKey();
192	        boolean identityInUse = this.clinicService.findAllOwners().stream()
193	            .filter(existing -> !existing.isDeleted())
194	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
195	        if (identityInUse) {
196	            throw new ResponseStatusException(HttpStatus.CONFLICT,
197	                "An owner with this identity already exists");
198	        }
199	        // Duplicate detection is now the single identity key above; because the telephone is part of
200	        // that key, two owners sharing a last name and postcode but with different telephones have
201	        // different keys and are both admitted, so the former household-duplicate 409 no longer
202	        // applies. Declaring 'sharesHousehold' marks the new owner as a declared household member.
203	        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
204	        // An undeclared new owner joining an existing household while carrying its own (distinct)
205	        // email address joins as a member whose membership level is capped below.
206	        boolean distinguishableByEmail = owner.getEmail() != null && !owner.getEmail().isBlank()
207	            && householdMembers.stream()
208	                .noneMatch(existing -> owner.getEmail().equalsIgnoreCase(existing.getEmail()));
209	        boolean joinsExistingHousehold = !householdMembers.isEmpty()
210	            && !declaredHouseholdMember && distinguishableByEmail;
211	        String cityKey = normalizeForHousehold(owner.getCity());
212	        long cityCount = this.clinicService.findAllOwners().stream()
213	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(cityKey))
214	            .count();
215	        if (cityCount >= 50) {
216	            throw new ResponseStatusException(HttpStatus.CONFLICT,
217	                "This city already has the maximum number of owners");
218	        }
219	        // Approaching the per-city capacity limit (50): warn once the city already holds 40-49
220	        // owners. Fixed at creation time, mirroring bulkSignupWarning. The >= 50 case is rejected
221	        // above, so cityCount is guaranteed below 50 here.
222	        owner.setCapacityWarning(cityCount >= 40);
223	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
224	        owner.setHouseholdSize(householdMembers.size() + 1);
225	        // A new owner joining an existing household cannot rank more than one level above the current
226	        // maximum membership level among their household members: its level is capped there. With no
227	        // existing household member (the usual case) no cap applies and the level stays as derived.
228	        if (joinsExistingHousehold) {
229	            int naturalLevel = Owner.membershipLevel(Owner.membershipPoints(owner));
230	            int maxMemberLevel = householdMembers.stream()
231	                .mapToInt(Owner::effectiveMembershipLevel)
232	                .max().orElse(0);
233	            owner.setMembershipLevel(Math.min(naturalLevel, maxMemberLevel + 1));
234	        }
235	        // Soft match: a new owner whose identityKey differs from every existing owner but whose
236	        // soundex(lastName) and postcode both match an existing (non-deleted) owner is flagged as a
237	        // possible duplicate of the earliest such owner. Soft-deleted owners are ignored, matching
238	        // the identity check above.
239	        String lastNameSoundex = Owner.soundex(owner.getLastName());
240	        Owner softMatch = this.clinicService.findAllOwners().stream()
241	            .filter(existing -> !existing.isDeleted())
242	            .filter(existing -> !identityKey.equals(existing.getIdentityKey()))
243	            .filter(existing -> owner.getPostcode() != null
244	                && owner.getPostcode().equals(existing.getPostcode()))
245	            .filter(existing -> lastNameSoundex.equals(Owner.soundex(existing.getLastName())))
246	            .min(java.util.Comparator.comparing(Owner::getId))
247	            .orElse(null);
248	        if (softMatch != null) {
249	            owner.setPossibleDuplicate(true);
250	            owner.setPossibleDuplicateOf(softMatch.getId());
251	        } else {
252	            owner.setPossibleDuplicate(false);
253	            owner.setPossibleDuplicateOf(null);
254	        }
255	        owner.setMemberId(deduplicateMemberId(memberId(owner.getCity(), owner.getPostcode(),
256	            owner.getTelephone(), owner.getLastName(), owner.getRegistrationDate())));
257	        this.clinicService.saveOwner(owner);
258	        if (idempotencyKey != null) {
259	            IDEMPOTENCY_KEYS.put(idempotencyKey, owner.getId());
260	        }
261	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
262	        AUDIT.info("Owner created: id={} memberId={} registrationDate={} membershipLevel={}",
263	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), ownerDto.getMembershipLevel());
264	        // The event's primary identifier is the owner's unified memberId.
265	        String primaryIdentifier = owner.getMemberId();
266	        OwnerCreatedEvent event = new OwnerCreatedEvent(OWNER_EVENT_SEQ.incrementAndGet(),
267	            owner.getId(), primaryIdentifier, ownerDto.getMembershipLevel(), "OWNER_CREATED");
268	        AUDIT.info(AUDIT_EVENT_MAPPER.writeValueAsString(event));
269	        // Enqueue a welcome notification for the newly created owner, carrying the owner id and the
270	        // unified memberId so downstream notification handling can address the new member.
271	        NOTIFY.info("Welcome notification enqueued: ownerId={} memberId={}",
272	            owner.getId(), owner.getMemberId());
273	        headers.setLocation(UriComponentsBuilder.newInstance()
274	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
275	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
276	    }
