298	    /**
299	     * The fixed public-holiday calendar the business-day roll skips. When an adjusted registration
300	     * date lands on one of these dates it is rolled forward to the next non-holiday business day.
301	     */
302	    private static final java.util.Set<java.time.LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
303	        java.time.LocalDate.parse("2026-01-01"), java.time.LocalDate.parse("2026-01-26"),
304	        java.time.LocalDate.parse("2026-04-25"), java.time.LocalDate.parse("2026-12-25"),
305	        java.time.LocalDate.parse("2026-12-28"));
