307	    /**
308	     * Rolls a registration date forward to a business day. A Saturday, Sunday or listed public
309	     * holiday is advanced one day at a time until it lands on a weekday that is not a public holiday;
310	     * a plain weekday is returned unchanged. This is applied to the effective registration date
311	     * (whether supplied in the request or defaulted to the server date) so that every stored
312	     * {@code registrationDate}, and any value derived from it, lands on a business day.
313	     *
314	     * @param date the effective registration date
315	     * @return the same date if it is a non-holiday weekday, otherwise the next non-holiday business day
316	     */
317	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
318	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
319	            || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
320	            || PUBLIC_HOLIDAYS.contains(date)) {
321	            date = date.plusDays(1);
322	        }
323	        return date;
324	    }
