344	    /**
345	     * Builds the unified member id for a new owner, formatted {@code '<REGION><FY><HASH8><CHK>'}.
346	     * {@code REGION} is the canonical region derived from the owner's postcode (falling back to
347	     * the city when the postcode is absent or in no known range, see
348	     * {@link org.springframework.samples.petclinic.mapper.Localities#forCityAndPostcode}).
349	     * {@code FY} is the 2-digit fiscal year of the (business-day-adjusted) registration date.
350	     * {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest of the
351	     * normalized telephone concatenated with the last name (the same HASH8 the region-and-hash
352	     * identity used). {@code CHK} is a single Luhn check digit computed over the digits of the
353	     * {@code <REGION><FY><HASH8>} prefix (e.g. {@code 'NSW261A2B3C4D7'}). It is a pure function of
354	     * the owner's region, fiscal year, telephone and last name.
355	     *
356	     * @param city                the owner's city
357	     * @param postcode            the owner's postcode, may be {@code null}
358	     * @param normalizedTelephone the owner's telephone, already normalized to E.164
359	     * @param lastName            the owner's last name
360	     * @param registrationDate    the owner's business-day-adjusted registration date
361	     * @return the assigned member id
362	     */
363	    private String memberId(String city, String postcode, String normalizedTelephone, String lastName,
364	            java.time.LocalDate registrationDate) {
365	        String region = org.springframework.samples.petclinic.mapper.Localities
366	            .forCityAndPostcode(city, postcode);
367	        String fy = Owner.fiscalYearLabel(registrationDate).substring(2);
368	        String hash8 = sha256UpperHex((normalizedTelephone == null ? "" : normalizedTelephone)
369	            + (lastName == null ? "" : lastName), 8);
370	        String prefix = region + fy + hash8;
371	        return prefix + Owner.luhnCheckDigit(prefix);
372	    }
