374	    /**
375	     * Ensures the computed {@code memberId} is unique across existing owners. When {@code baseId}
376	     * does not collide with any existing owner's {@code memberId} it is returned unchanged.
377	     * Otherwise {@code '-<n>'} is appended, using the smallest {@code n} of 2 or more that yields a
378	     * value not already in use, and that de-duplicated id is returned.
379	     *
380	     * @param baseId the freshly computed member id
381	     * @return {@code baseId} if unused, otherwise {@code baseId + "-" + n} for the smallest free n
382	     */
383	    private String deduplicateMemberId(String baseId) {
384	        java.util.Set<String> inUse = this.clinicService.findAllOwners().stream()
385	            .map(org.springframework.samples.petclinic.model.Owner::getMemberId)
386	            .filter(java.util.Objects::nonNull)
387	            .collect(java.util.stream.Collectors.toSet());
388	        if (!inUse.contains(baseId)) {
389	            return baseId;
390	        }
391	        int n = 2;
392	        while (inUse.contains(baseId + "-" + n)) {
393	            n++;
394	        }
395	        return baseId + "-" + n;
396	    }
