398	    /**
399	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the
400	     * UTF-8 bytes of {@code value}.
401	     *
402	     * @param value  the source value to hash
403	     * @param length the number of leading hex characters to return
404	     * @return the leading upper-case hex characters of the digest
405	     */
406	    private String sha256UpperHex(String value, int length) {
407	        try {
408	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
409	                .digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
410	            StringBuilder sb = new StringBuilder(digest.length * 2);
411	            for (byte b : digest) {
412	                sb.append(String.format("%02x", b));
413	            }
414	            return sb.substring(0, length).toUpperCase(java.util.Locale.ROOT);
415	        }
416	        catch (java.security.NoSuchAlgorithmException e) {
417	            throw new IllegalStateException("SHA-256 not available", e);
418	        }
419	    }
