421	    /**
422	     * Normalizes a street address applied whenever an owner is created: leading and trailing
423	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the
424	     * value is upper-cased, and common street-type abbreviations are expanded to their full form
425	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The expansion is applied
426	     * per whitespace-delimited token, so only standalone abbreviations are expanded. A {@code null}
427	     * value normalizes to the empty string. So {@code '  12  main  st '} becomes
428	     * {@code '12 MAIN STREET'}.
429	     *
430	     * @param address the raw address as submitted, or {@code null} when absent
431	     * @return the normalized address, or the empty string when the value is blank
432	     */
433	    /**
434	     * Resolves and normalizes an owner's postal address, accepting either the structured form
435	     * ({@code addressLine1} plus an optional {@code addressLine2}) or the flat {@code address}
436	     * input for backward compatibility. The structured form is preferred: when a non-blank
437	     * {@code addressLine1} is supplied, both structured lines are normalized (see
438	     * {@link #normalizeAddress(String)}) and the stored {@code address} is composed from them —
439	     * the normalized {@code addressLine1}, with a single space and the normalized
440	     * {@code addressLine2} appended when an {@code addressLine2} is present. Otherwise the flat
441	     * {@code address} input is normalized and stored, and the structured lines are cleared.
442	     *
443	     * <p>An owner is valid only when it supplies an address in one of these forms; a request with
444	     * neither a non-blank {@code addressLine1} nor a non-blank flat {@code address} is rejected.
445	     *
446	     * @param owner the owner whose address fields are resolved and normalized in place
447	     * @throws ResponseStatusException with a 400 status when no address is supplied in either form
448	     */
449	    private void applyAddress(Owner owner) {
450	        String line1 = normalizeAddress(owner.getAddressLine1());
451	        String line2 = normalizeAddress(owner.getAddressLine2());
452	        String flat = normalizeAddress(owner.getAddress());
453	        String composed;
454	        if (!line1.isEmpty()) {
455	            composed = line2.isEmpty() ? line1 : line1 + " " + line2;
456	            owner.setAddressLine1(line1);
457	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
458	        } else {
459	            composed = flat;
460	            owner.setAddressLine1(null);
461	            owner.setAddressLine2(null);
462	        }
463	        if (composed.isEmpty()) {
464	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
465	                "Address must not be blank after normalization");
466	        }
467	        owner.setAddress(composed);
468	    }
