470	    private String normalizeAddress(String address) {
471	        String collapsed = (address == null ? "" : address)
472	            .trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
473	        if (collapsed.isEmpty()) {
474	            return "";
475	        }
476	        String[] tokens = collapsed.split(" ");
477	        for (int i = 0; i < tokens.length; i++) {
478	            switch (tokens[i]) {
479	                case "ST" -> tokens[i] = "STREET";
480	                case "RD" -> tokens[i] = "ROAD";
481	                case "AVE" -> tokens[i] = "AVENUE";
482	                default -> { }
483	            }
484	        }
485	        return String.join(" ", tokens);
486	    }
