488	    /**
489	     * Normalizes a value for household-duplicate comparison: leading and trailing whitespace is
490	     * trimmed, any internal run of whitespace is collapsed to a single space, and the result is
491	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to the
492	     * empty string.
493	     *
494	     * @param value the raw value (last name or address) as submitted
495	     * @return the normalized comparison key
496	     */
497	    private String normalizeForHousehold(String value) {
498	        if (value == null) {
499	            return "";
500	        }
501	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
502	    }
