504	    /**
505	     * Derives the stable shared household identifier for a household, keyed on the normalized last
506	     * name and address. Because it is a pure function of those normalized keys, every owner in the
507	     * same household deterministically computes the same value. The identifier is the first 12
508	     * upper-case hex characters of the SHA-256 digest of the two keys joined with a NUL separator
509	     * (the separator prevents distinct name/address pairs from colliding).
510	     *
511	     * @param lastNameKey the normalized last-name comparison key
512	     * @param addressKey  the normalized address comparison key
513	     * @return the stable household identifier
514	     */
515	    private String householdId(String lastNameKey, String postcode) {
516	        String seed = lastNameKey + "|" + (postcode == null ? "" : postcode);
517	        try {
518	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
519	                .digest(seed.getBytes(java.nio.charset.StandardCharsets.UTF_8));
520	            StringBuilder sb = new StringBuilder(digest.length * 2);
521	            for (byte b : digest) {
522	                sb.append(String.format("%02x", b));
523	            }
524	            return sb.substring(0, 12).toUpperCase(java.util.Locale.ROOT);
525	        }
526	        catch (java.security.NoSuchAlgorithmException e) {
527	            throw new IllegalStateException("SHA-256 not available", e);
528	        }
529	    }
