531	    /**
532	     * The exact number of national (subscriber) digits required for a given country calling code,
533	     * i.e. the digits that follow the country code in an E.164 number. A country code that is not
534	     * listed here has no fixed-length requirement beyond the general 8-to-15-digit E.164 bound.
535	     * Australia ({@code '+61'}) requires 9 national digits and the NANP ({@code '+1'}) requires 10.
536	     */
537	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
538	        java.util.Map.of("61", 9, "1", 10);
539	
540	    /**
541	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets (indeed any
542	     * non-digit character) are stripped. If the submitted value carries a leading {@code '+'}
543	     * its country code is kept as-is; otherwise the default country code {@code '+61'} is
544	     * assumed and a single leading {@code '0'} is dropped from the national digits. The
545	     * resulting value must be a {@code '+'} followed by 8 to 15 digits. So {@code '0412 345 678'}
546	     * is stored as {@code '+61412345678'}.
547	     *
548	     * <p>In addition, when the number's country code has a fixed national-number length (see
549	     * {@link #NATIONAL_NUMBER_LENGTHS}), the national digits that follow the country code must
550	     * match that length exactly: {@code '+61'} requires 9 national digits and {@code '+1'}
551	     * requires 10. So {@code '+61 123'} is rejected because its 3 national digits are not 9.
552	     *
553	     * @param telephone the raw telephone number as submitted
554	     * @return the normalized E.164 telephone number
555	     * @throws ResponseStatusException with a 400 status if the value cannot form a valid E.164
556	     *         number (8 to 15 digits after the '+'), or if its national-number length is wrong
557	     *         for its country code
558	     */
559	    private String normalizeTelephone(String telephone) {
560	        String raw = telephone == null ? "" : telephone.trim();
561	        String digits = raw.replaceAll("\\D", "");
562	        String e164;
563	        if (raw.startsWith("+")) {
564	            e164 = "+" + digits;
565	        } else {
566	            if (digits.startsWith("0")) {
567	                digits = digits.substring(1);
568	            }
569	            e164 = "+61" + digits;
570	        }
571	        int digitCount = e164.length() - 1;
572	        if (digitCount < 8 || digitCount > 15) {
573	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
574	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
575	        }
576	        validateNationalNumberLength(e164);
577	        return e164;
578	    }
579	
580	    /**
581	     * Validates that an E.164 number's national-number length is correct for its country code.
582	     * The country code is matched by longest known prefix (so {@code '+61'} is preferred over
583	     * {@code '+1'} would-be matches); when the code has a fixed national-number length the digits
584	     * following it must match exactly. Country codes without a fixed length are left unchecked.
585	     *
586	     * @param e164 the normalized E.164 number (a {@code '+'} followed by digits)
587	     * @throws ResponseStatusException with a 400 status if the national-number length is wrong
588	     *         for the country code
589	     */
590	    private void validateNationalNumberLength(String e164) {
591	        String allDigits = e164.substring(1);
592	        String bestCode = null;
593	        for (String code : NATIONAL_NUMBER_LENGTHS.keySet()) {
594	            if (allDigits.startsWith(code)
595	                    && (bestCode == null || code.length() > bestCode.length())) {
596	                bestCode = code;
597	            }
598	        }
599	        if (bestCode == null) {
600	            return;
601	        }
602	        int nationalLength = allDigits.length() - bestCode.length();
603	        int required = NATIONAL_NUMBER_LENGTHS.get(bestCode);
604	        if (nationalLength != required) {
605	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
606	                "Telephone for country code '+" + bestCode + "' must have " + required
607	                    + " national digits");
608	        }
609	    }
