611	    /**
612	     * The inclusive 4-digit postcode range permitted for each canonical region, keyed by the
613	     * region derived from the owner's city ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
614	     * {@code Brisbane -> QLD}): NSW {@code 2000-2099}, VIC {@code 3000-3099}, QLD
615	     * {@code 4000-4099}. A city whose region is not listed here accepts any 4-digit postcode.
616	     */
617	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
618	        "NSW", new int[] {2000, 2099},
619	        "VIC", new int[] {3000, 3099},
620	        "QLD", new int[] {4000, 4099});
