622	    /**
623	     * Validates an owner's optional postcode against their city's region. The postcode is only
624	     * checked when present (a {@code null} postcode is accepted, keeping the request contract
625	     * backward-compatible). Its four-digit shape is already enforced by Bean Validation on the
626	     * request DTO. When the city maps to a known region (see {@link #REGION_POSTCODE_RANGES}) the
627	     * postcode must fall within that region's inclusive range; a city with no known region accepts
628	     * any 4-digit postcode.
629	     *
630	     * @param postcode the owner's postcode as submitted, or {@code null} when absent
631	     * @param city     the owner's city, used to derive the region whose range applies
632	     * @throws ResponseStatusException with a 400 status when a supplied postcode is out of range
633	     *         for the city's region
634	     */
635	    private void validatePostcode(String postcode, String city) {
636	        if (postcode == null) {
637	            return;
638	        }
639	        String region = org.springframework.samples.petclinic.mapper.Localities.forCity(city);
640	        int[] range = REGION_POSTCODE_RANGES.get(region);
641	        if (range == null) {
642	            return;
643	        }
644	        int value = Integer.parseInt(postcode);
645	        if (value < range[0] || value > range[1]) {
646	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
647	                "Postcode " + postcode + " is not valid for region " + region);
648	        }
649	    }
