663	    /**
664	     * The set of disposable email domains an owner's email may not use. These throwaway-mailbox
665	     * providers are rejected because they cannot be relied on for durable contact.
666	     */
667	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
668	        "mailinator.com", "tempmail.com", "guerrillamail.com");
669	
670	    /**
671	     * Rejects an owner whose email domain is on the disposable-domain blocklist. The email has
672	     * already been normalized to lower-case, so the domain (the part after the last {@code '@'}) is
673	     * compared case-insensitively against {@link #DISPOSABLE_EMAIL_DOMAINS}. A {@code null} email
674	     * (absent) is accepted, keeping the field optional.
675	     *
676	     * @param email the normalized email address, or {@code null} when absent
677	     * @throws ResponseStatusException with a 400 status when the email domain is blocklisted
678	     */
679	    private void validateEmailDomain(String email) {
680	        if (email == null) {
681	            return;
682	        }
683	        int at = email.lastIndexOf('@');
684	        if (at < 0) {
685	            return;
686	        }
687	        String domain = email.substring(at + 1);
688	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
689	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
690	                "Email domain " + domain + " is not allowed");
691	        }
692	    }
