696	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
697	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
698	        if (currentOwner == null) {
699	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
700	        }
701	        currentOwner.setAddress(ownerFieldsDto.getAddress());
702	        currentOwner.setCity(ownerFieldsDto.getCity());
703	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
704	        currentOwner.setLastName(ownerFieldsDto.getLastName());
705	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
706	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
707	        this.clinicService.saveOwner(currentOwner);
708	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
709	    }
710	
711	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
712	    @Transactional
713	    @Override
714	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
715	        Owner owner = this.clinicService.findOwnerById(ownerId);
716	        if (owner == null) {
717	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
718	        }
719	        // Soft delete: flag the owner deleted and retain the row rather than removing it.
720	        owner.setDeleted(true);
721	        this.clinicService.saveOwner(owner);
722	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
723	    }
724	
725	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
726	    @Override
727	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
728	        Owner owner = this.clinicService.findOwnerById(ownerId);
729	        if (owner == null) {
730	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
731	        }
732	        HttpHeaders headers = new HttpHeaders();
733	        Pet pet = petMapper.toPet(petFieldsDto);
734	        owner.setId(ownerId);
735	        pet.setOwner(owner);
736	        pet.getType().setName(null);
737	        this.clinicService.savePet(pet);
738	        PetDto petDto = petMapper.toPetDto(pet);
739	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
740	            .buildAndExpand(pet.getId()).toUri());
741	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
742	    }
743	
744	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
745	    @Override
746	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
747	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
748	        if (currentOwner != null) {
749	            Pet currentPet = this.clinicService.findPetById(petId);
750	            if (currentPet != null) {
751	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
752	                currentPet.setName(petFieldsDto.getName());
753	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
754	                this.clinicService.savePet(currentPet);
755	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
756	            }
757	        }
758	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
759	    }
760	
761	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
762	    @Override
763	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
764	        HttpHeaders headers = new HttpHeaders();
765	        Visit visit = visitMapper.toVisit(visitFieldsDto);
766	        Pet pet = new Pet();
767	        pet.setId(petId);
768	        visit.setPet(pet);
769	        this.clinicService.saveVisit(visit);
770	        VisitDto visitDto = visitMapper.toVisitDto(visit);
771	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
772	            .buildAndExpand(visit.getId()).toUri());
773	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
774	    }
