246	    /**
247	     * Derives the owner's age band from a birth date, computed against the reference date
248	     * (the registration date): {@code 'MINOR'} when under 18, {@code 'ADULT'} from 18 to 64,
249	     * and {@code 'SENIOR'} at 65 or older. The completed-years age is the whole number of years
250	     * between the birth date and the reference date. Returns {@code null} when no birth date is
251	     * supplied. When the reference date is absent the current server date is used.
252	     *
253	     * @param birthDate the owner's date of birth, or {@code null} when absent
254	     * @param reference the date to compute the age against (the registration date), may be {@code null}
255	     * @return {@code 'MINOR'}, {@code 'ADULT'} or {@code 'SENIOR'}, or {@code null} when no birth date
256	     */
257	    public static String ageBandOf(LocalDate birthDate, LocalDate reference) {
258	        if (birthDate == null) {
259	            return null;
260	        }
261	        LocalDate asOf = reference != null ? reference : LocalDate.now();
262	        int years = java.time.Period.between(birthDate, asOf).getYears();
263	        if (years < 18) {
264	            return "MINOR";
265	        }
266	        if (years < 65) {
267	            return "ADULT";
268	        }
269	        return "SENIOR";
270	    }
271	
272	    /**
273	     * The starting calendar year of the fiscal year that contains the given date. The fiscal year
274	     * starts on 1 July, so a date in July or later belongs to the fiscal year starting that same
275	     * calendar year, while a date from January to June belongs to the fiscal year that started in
276	     * the previous calendar year.
277	     *
278	     * @param date the date to classify
279	     * @return the calendar year in which the containing fiscal year starts
280	     */
281	    public static int fiscalYearNumber(LocalDate date) {
282	        return date.getMonthValue() >= java.time.Month.JULY.getValue()
283	            ? date.getYear() : date.getYear() - 1;
284	    }
285	
286	    /**
287	     * The fiscal year that contains the given date, formatted {@code 'FY<YY>'} where YY is the last
288	     * two digits of the fiscal year's starting calendar year. For example a date on or after 1 July
289	     * 2026 yields {@code 'FY26'}. The fiscal year starts on 1 July.
290	     *
291	     * @param date the date to classify, which for an owner is the business-day-adjusted registration date
292	     * @return the fiscal year label, e.g. {@code 'FY26'}
293	     */
294	    public static String fiscalYearLabel(LocalDate date) {
295	        return String.format("FY%02d", fiscalYearNumber(date) % 100);
296	    }
297	
298	    /**
299	     * Whether the owner's tenure — the number of elapsed fiscal years from the registration date to
300	     * the current server date — exceeds one year (strictly more than one elapsed fiscal year). The
301	     * elapsed count is the difference between the fiscal year of the current server date and the
302	     * fiscal year of the registration date. This gates the top membership level: only an owner past
303	     * a full year of tenure can reach level 4. A {@code null} registration date counts as zero
304	     * tenure and so never exceeds the threshold, which is why a newly created owner (zero tenure)
305	     * can never exceed level 3.
306	     *
307	     * @param registrationDate the date the owner registered, or {@code null} when absent
308	     * @return {@code true} when more than one fiscal year has elapsed since registration
309	     */
310	    public static boolean tenureExceedsOneYear(LocalDate registrationDate) {
311	        if (registrationDate == null) {
312	            return false;
313	        }
314	        return fiscalYearNumber(LocalDate.now()) - fiscalYearNumber(registrationDate) > 1;
315	    }
316	
317	    /**
318	     * The owner's membership points, accumulated from the membership factors. Points start at 0 and
319	     * gain 2 when an email address is present, 1 when the owner has no namesakes (namesakeCount is
320	     * 0), 2 for a household of 3 or more members, and 3 when the owner's tenure exceeds one year.
321	     *
322	     * @param owner the owner to score
323	     * @return the total membership points (never negative)
324	     */
325	    public static int membershipPoints(Owner owner) {
326	        int points = 0;
327	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
328	            points += 2;
329	        }
330	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
331	            points += 1;
332	        }
333	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
334	            points += 2;
335	        }
336	        if (tenureExceedsOneYear(owner.getRegistrationDate())) {
337	            points += 3;
338	        }
339	        return points;
340	    }
341	
342	    /**
343	     * Maps membership points to the numeric membership level: 1 for 0-1 points, 2 for 2-3, 3 for
344	     * 4-5, and 4 for 6 or more.
345	     *
346	     * @param points the owner's membership points
347	     * @return the membership level, from 1 to 4
348	     */
349	    public static int membershipLevel(int points) {
350	        if (points <= 1) {
351	            return 1;
352	        }
353	        if (points <= 3) {
354	            return 2;
355	        }
356	        if (points <= 5) {
357	            return 3;
358	        }
359	        return 4;
360	    }
361	
362	    /**
363	     * The owner's effective membership level: the explicitly stored {@link #membershipLevel} when one
364	     * was fixed at creation (for example, an owner whose level was capped to one above their
365	     * household), otherwise the level derived live from {@link #membershipPoints(Owner)}.
366	     *
367	     * @param owner the owner to score
368	     * @return the effective membership level
369	     */
370	    public static int effectiveMembershipLevel(Owner owner) {
371	        if (owner.getMembershipLevel() != null) {
372	            return owner.getMembershipLevel();
373	        }
374	        return membershipLevel(membershipPoints(owner));
375	    }
