457	    /**
458	     * The single derived key used for all duplicate detection: the lower-case hex SHA-256 digest of
459	     * {@code '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>'}. Two owners are duplicates
460	     * only when their whole identity keys are equal; because the telephone is part of the key, two
461	     * members of the same household with different telephones have different keys and are both
462	     * allowed.
463	     *
464	     * @return the derived identity key as 64 lower-case hex characters
465	     */
466	    @Transient
467	    public String getIdentityKey() {
468	        String seed = (this.telephone == null ? "" : this.telephone) + "|"
469	            + (this.email == null ? "" : this.email.toLowerCase(Locale.ROOT)) + "|"
470	            + soundex(this.getLastName());
471	        return sha256Hex(seed);
472	    }
473	
474	    /**
475	     * The full lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
476	     *
477	     * @param value the source value to hash
478	     * @return the 64-character lower-case hex digest
479	     */
480	    private static String sha256Hex(String value) {
481	        try {
482	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
483	                .digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
484	            StringBuilder sb = new StringBuilder(digest.length * 2);
485	            for (byte b : digest) {
486	                sb.append(String.format("%02x", b));
487	            }
488	            return sb.toString();
489	        }
490	        catch (java.security.NoSuchAlgorithmException e) {
491	            throw new IllegalStateException("SHA-256 not available", e);
492	        }
493	    }
494	
495	    /**
496	     * The American Soundex code of a name: its first letter followed by three digits derived from
497	     * the remaining consonants ({@code b,f,p,v -> 1}; {@code c,g,j,k,q,s,x,z -> 2}; {@code d,t -> 3};
498	     * {@code l -> 4}; {@code m,n -> 5}; {@code r -> 6}; vowels and {@code h,w} are not coded).
499	     * Adjacent letters mapping to the same digit (including when separated only by {@code h} or
500	     * {@code w}) are coded once, while a vowel between them resets the run so the digit is coded
501	     * again. The code is right-padded with zeros and truncated to length four. A {@code null} or
502	     * letter-free name yields {@code '0000'}.
503	     *
504	     * @param name the name to encode
505	     * @return the four-character Soundex code
506	     */
507	    public static String soundex(String name) {
508	        String s = (name == null ? "" : name).toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
509	        if (s.isEmpty()) {
510	            return "0000";
511	        }
512	        char first = s.charAt(0);
513	        StringBuilder code = new StringBuilder().append(first);
514	        char prevDigit = soundexDigit(first);
515	        for (int i = 1; i < s.length() && code.length() < 4; i++) {
516	            char c = s.charAt(i);
517	            char digit = soundexDigit(c);
518	            if (digit != '0' && digit != prevDigit) {
519	                code.append(digit);
520	            }
521	            if (c != 'H' && c != 'W') {
522	                prevDigit = digit;
523	            }
524	        }
525	        while (code.length() < 4) {
526	            code.append('0');
527	        }
528	        return code.toString();
529	    }
530	
531	    /**
532	     * Maps a single upper-case letter to its Soundex digit, or {@code '0'} for vowels and the
533	     * uncoded letters {@code h} and {@code w}.
534	     *
535	     * @param c the upper-case letter to map
536	     * @return the Soundex digit character, or {@code '0'} when the letter is not coded
537	     */
538	    private static char soundexDigit(char c) {
539	        switch (c) {
540	            case 'B': case 'F': case 'P': case 'V':
541	                return '1';
542	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
543	                return '2';
544	            case 'D': case 'T':
545	                return '3';
546	            case 'L':
547	                return '4';
548	            case 'M': case 'N':
549	                return '5';
550	            case 'R':
551	                return '6';
552	            default:
553	                return '0';
554	        }
555	    }
556	
557	    /**
558	     * A single Luhn check digit (0-9) computed over the digits contained in {@code source}.
559	     * Non-digit characters (such as letter prefixes and separators) are ignored; a {@code null}
560	     * source is treated as having no digits. This is the CHK segment of the owner's
561	     * {@code memberId}, computed over the digits of its {@code <REGION><FY><HASH8>} prefix.
562	     *
563	     * @param source the string whose digits the check digit is computed over
564	     * @return the Luhn check digit (0-9)
565	     */
566	    public static int luhnCheckDigit(String source) {
567	        if (source == null) {
568	            source = "";
569	        }
570	        int sum = 0;
571	        boolean dbl = true;
572	        for (int i = source.length() - 1; i >= 0; i--) {
573	            char c = source.charAt(i);
574	            if (c < '0' || c > '9') {
575	                continue;
576	            }
577	            int d = c - '0';
578	            if (dbl) {
579	                d *= 2;
580	                if (d > 9) {
581	                    d -= 9;
582	                }
583	            }
584	            sum += d;
585	            dbl = !dbl;
586	        }
587	        return (10 - (sum % 10)) % 10;
588	    }
589	
590	    protected Set<Pet> getPetsInternal() {
591	        if (this.pets == null) {
592	            this.pets = new HashSet<>();
593	        }
