601	    public List<Pet> getPets() {
602	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
603	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
604	        return Collections.unmodifiableList(sortedPets);
605	    }
