616	    /**
617	     * Return the Pet with the given name, or null if none found for this Owner.
618	     *
619	     * @param name to test
620	     * @return true if pet name is already in use
621	     */
622	    public Pet getPet(String name) {
623	        return getPet(name, false);
624	    }
625	
626	    /**
627	     * Return the Pet with the given name, or null if none found for this Owner.
628	     *
629	     * @param name to test
630	     * @return true if pet name is already in use
631	     */
632	    public Pet getPet(String name, boolean ignoreNew) {
633	        name = name.toLowerCase();
634	        for (Pet pet : getPetsInternal()) {
635	            if (!ignoreNew || !pet.isNew()) {
636	                String compName = pet.getName();
637	                compName = compName.toLowerCase();
638	                if (compName.equals(name)) {
639	                    return pet;
640	                }
641	            }
642	        }
643	        return null;
644	    }
645	
646	    public Pet getPet(Integer petId) {
647	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
648	    }
649	
650	    @Override
651	    public String toString() {
652	        return new ToStringCreator(this)
653	
654	            .append("id", this.getId())
655	            .append("new", this.isNew())
656	            .append("lastName", this.getLastName())
657	            .append("firstName", this.getFirstName())
658	            .append("address", this.address)
659	            .append("city", this.city)
660	            .append("telephone", this.telephone)
661	            .toString();
662	    }
663	}
